/**
 * Service worker registration without workbox-window. The worker is generated by
 * vite-plugin-pwa in "prompt" mode: a new version waits until the user agrees to restart,
 * so an update never reloads the page in the middle of work.
 */
export function registerServiceWorker(onUpdateReady: (apply: () => void) => void): void {
  if (import.meta.env.DEV || !('serviceWorker' in navigator)) return;
  const sw = navigator.serviceWorker;
  let applying = false;

  const offer = (worker: ServiceWorker) =>
    onUpdateReady(() => {
      applying = true;
      worker.postMessage({ type: 'SKIP_WAITING' });
    });

  sw.addEventListener('controllerchange', () => {
    if (applying) location.reload();
  });

  window.addEventListener('load', async () => {
    try {
      const registration = await sw.register('./sw.js', { scope: './' });
      if (registration.waiting && sw.controller) offer(registration.waiting);
      registration.addEventListener('updatefound', () => {
        const worker = registration.installing;
        worker?.addEventListener('statechange', () => {
          if (worker.state === 'installed' && sw.controller) offer(worker);
        });
      });
      // Long sessions are normal for an editor: look for a new version every hour.
      setInterval(() => registration.update().catch(() => {}), 60 * 60 * 1000);
    } catch (error) {
      console.warn('Service worker registration failed', error);
    }
  });
}
